package com.yeyamo_mobile.api.gamification_service.application.badge;import java.util.*;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.gamification_service.domain.*;
@Component public class MilestoneBadgeRule implements BadgeRule{public List<BadgeDefinition>evaluate(Progress p,Map<String,Long>c){List<BadgeDefinition>r=new ArrayList<>();add(r,c.getOrDefault("POST",0L)>=1,"FIRST_POST","Premier récit","Publier un premier contenu");add(r,c.getOrDefault("CHECKIN",0L)>=1,"EXPLORER","Explorateur","Effectuer un premier check-in");add(r,c.getOrDefault("CHECKIN",0L)>=5,"TRAVELER_5","Voyageur","Visiter cinq destinations");add(r,c.getOrDefault("SOCIAL",0L)>=10,"SOCIAL_10","Sociable","Réaliser dix interactions");add(r,c.getOrDefault("BOOKING",0L)>=1,"FIRST_BOOKING","Premier voyage réservé","Confirmer une première réservation");add(r,p.currentStreak()>=7,"STREAK_7","Série de 7 jours","Être actif sept jours consécutifs");add(r,p.level()>=5,"LEVEL_5","Niveau 5","Atteindre le niveau 5");return r;}private void add(List<BadgeDefinition>r,boolean condition,String code,String name,String description){if(condition)r.add(new BadgeDefinition(code,name,description));}}
